// Validate BPM range for house music
const bpm = $input.first().json.bpm || 128;
const bars = $input.first().json.bars || 16;
const key = $input.first().json.key || 'A';
const scale = $input.first().json.scale || 'minor';

// Ensure BPM is in house music range (120-140)
const validatedBpm = Math.max(120, Math.min(140, bpm));

if (bpm !== validatedBpm) {
  console.log(`BPM adjusted from ${bpm} to ${validatedBpm} to fit house music range (120-140)`);
}

return {
  json: {
    bpm: validatedBpm,
    bars: bars,
    key: key,
    scale: scale,
    timestamp: new Date().toISOString()
  }
};

// House Music Drum Pattern Generator (Embedded)
const bpm = $input.first().json.bpm;
const bars = $input.first().json.bars;
const ticksPerBeat = 480;
const beatsPerBar = 4;

const drumNotes = {
  kick: 36, snare: 38, closedHat: 42, openHat: 46,
  clap: 39, rimshot: 37, crash: 49
};

const midiEvents = [];
let eventId = 0;

// Kick (4 on the floor)
for (let bar = 0; bar < bars; bar++) {
  for (let beat = 0; beat < beatsPerBar; beat++) {
    const tick = (bar * beatsPerBar + beat) * ticksPerBeat;
    midiEvents.push({
      id: eventId++, type: 'noteOn', tick: tick,
      note: drumNotes.kick, velocity: beat === 0 ? 110 : 100,
      channel: 9, duration: ticksPerBeat / 2
    });
  }
}

// Snare/Clap (beats 2 and 4)
for (let bar = 0; bar < bars; bar++) {
  [1, 3].forEach(beat => {
    const tick = (bar * beatsPerBar + beat) * ticksPerBeat;
    const useClap = bar % 2 === 1;
    midiEvents.push({
      id: eventId++, type: 'noteOn', tick: tick,
      note: useClap ? drumNotes.clap : drumNotes.snare,
      velocity: 105, channel: 9, duration: ticksPerBeat / 2
    });
  });
}

// Hi-hats (8th notes)
for (let bar = 0; bar < bars; bar++) {
  for (let eighth = 0; eighth < beatsPerBar * 2; eighth++) {
    const tick = (bar * beatsPerBar * ticksPerBeat) + (eighth * ticksPerBeat / 2);
    const isOffbeat = eighth % 2 === 1;
    const isOpen = isOffbeat && (eighth === 3 || eighth === 7) && bar % 2 === 1;
    midiEvents.push({
      id: eventId++, type: 'noteOn', tick: tick,
      note: isOpen ? drumNotes.openHat : drumNotes.closedHat,
      velocity: isOffbeat ? 70 : 85, channel: 9,
      duration: ticksPerBeat / 4
    });
  }
}

// Crash on first beat
midiEvents.push({
  id: eventId++, type: 'noteOn', tick: 0,
  note: drumNotes.crash, velocity: 100,
  channel: 9, duration: ticksPerBeat * 2
});

midiEvents.sort((a, b) => a.tick - b.tick);

return {
  json: {
    instrument: 'drums',
    events: midiEvents,
    channel: 9
  }
};

// House Music Bass Pattern Generator (Embedded)
const params = $('Validate Parameters').first().json;
const { bpm, bars, key, scale } = params;
const ticksPerBeat = 480;
const beatsPerBar = 4;

const noteToMidi = {
  'C': 0, 'C#': 1, 'Db': 1, 'D': 2, 'D#': 3, 'Eb': 3, 'E': 4,
  'F': 5, 'F#': 6, 'Gb': 6, 'G': 7, 'G#': 8, 'Ab': 8,
  'A': 9, 'A#': 10, 'Bb': 10, 'B': 11
};

const scaleIntervals = {
  'minor': [0, 2, 3, 5, 7, 8, 10],
  'major': [0, 2, 4, 5, 7, 9, 11],
  'dorian': [0, 2, 3, 5, 7, 9, 10]
};

const rootNote = noteToMidi[key] + 24;
const intervals = scaleIntervals[scale] || scaleIntervals['minor'];
const scaleNotes = [];

for (let octave = 0; octave < 2; octave++) {
  intervals.forEach(interval => {
    scaleNotes.push(rootNote + interval + (octave * 12));
  });
}

const bassPatterns = [
  [
    { step: 0, note: 0, duration: 2, velocity: 100 },
    { step: 2, note: 0, duration: 1, velocity: 80 },
    { step: 4, note: 7, duration: 2, velocity: 90 },
    { step: 6, note: 0, duration: 1, velocity: 85 },
    { step: 8, note: 0, duration: 2, velocity: 100 },
    { step: 10, note: 3, duration: 1, velocity: 85 },
    { step: 12, note: 0, duration: 2, velocity: 95 },
    { step: 14, note: 7, duration: 1, velocity: 80 }
  ],
  [
    { step: 0, note: 0, duration: 1.5, velocity: 100 },
    { step: 2, note: 7, duration: 1, velocity: 85 },
    { step: 3.5, note: 0, duration: 1, velocity: 90 },
    { step: 5, note: 3, duration: 1.5, velocity: 85 },
    { step: 7, note: 0, duration: 1, velocity: 95 },
    { step: 8, note: 0, duration: 2, velocity: 100 },
    { step: 11, note: 5, duration: 1, velocity: 80 },
    { step: 13, note: 0, duration: 1.5, velocity: 90 },
    { step: 15, note: 7, duration: 0.5, velocity: 75 }
  ]
];

const midiEvents = [];
let eventId = 0;
const progressionDegrees = [0, 5, 2, 6];

for (let bar = 0; bar < bars; bar++) {
  const patternIndex = Math.floor(bar / 2) % bassPatterns.length;
  const pattern = bassPatterns[patternIndex];
  const chordRoot = progressionDegrees[bar % 4];

  pattern.forEach(note => {
    const tick = (bar * beatsPerBar * ticksPerBeat) + (note.step * ticksPerBeat / 4);
    const noteIndex = (chordRoot + note.note) % scaleNotes.length;
    midiEvents.push({
      id: eventId++, type: 'noteOn', tick: tick,
      note: scaleNotes[noteIndex], velocity: note.velocity,
      channel: 0, duration: (note.duration * ticksPerBeat / 4)
    });
  });
}

midiEvents.sort((a, b) => a.tick - b.tick);

return {
  json: {
    instrument: 'bass',
    events: midiEvents,
    channel: 0
  }
};

// House Music Chord Progression Generator (Embedded)
const params = $('Validate Parameters').first().json;
const { bpm, bars, key, scale } = params;
const ticksPerBeat = 480;
const beatsPerBar = 4;

const noteToMidi = {
  'C': 0, 'C#': 1, 'Db': 1, 'D': 2, 'D#': 3, 'Eb': 3, 'E': 4,
  'F': 5, 'F#': 6, 'Gb': 6, 'G': 7, 'G#': 8, 'Ab': 8,
  'A': 9, 'A#': 10, 'Bb': 10, 'B': 11
};

const scaleIntervals = {
  'minor': [0, 2, 3, 5, 7, 8, 10],
  'major': [0, 2, 4, 5, 7, 9, 11],
  'dorian': [0, 2, 3, 5, 7, 9, 10]
};

const chordTypes = {
  'minor7': [0, 3, 7, 10],
  'major7': [0, 4, 7, 11],
  'dominant7': [0, 4, 7, 10]
};

const rootNote = noteToMidi[key] + 48;
const intervals = scaleIntervals[scale] || scaleIntervals['minor'];
const scaleNotes = [];

for (let octave = 0; octave < 3; octave++) {
  intervals.forEach(interval => {
    scaleNotes.push(rootNote + interval + (octave * 12));
  });
}

const progression = [
  { degree: 0, type: 'minor7' },
  { degree: 5, type: 'major7' },
  { degree: 3, type: 'major7' },
  { degree: 6, type: 'dominant7' }
];

const rhythmPatterns = [
  [{ start: 0, duration: 16, velocity: 75 }],
  [
    { start: 0, duration: 3, velocity: 85 },
    { start: 4, duration: 2, velocity: 75 },
    { start: 7, duration: 2, velocity: 70 },
    { start: 10, duration: 3, velocity: 80 },
    { start: 14, duration: 2, velocity: 75 }
  ]
];

function buildChord(degree, type) {
  const baseNote = scaleNotes[degree];
  const chordIntervals = chordTypes[type];
  return chordIntervals.map(interval => baseNote + interval);
}

const midiEvents = [];
let eventId = 0;

for (let bar = 0; bar < bars; bar++) {
  const chordInfo = progression[bar % progression.length];
  const chord = buildChord(chordInfo.degree, chordInfo.type);
  const patternIndex = Math.floor(bar / 2) % rhythmPatterns.length;
  const rhythmPattern = rhythmPatterns[patternIndex];

  rhythmPattern.forEach(rhythm => {
    const tick = (bar * beatsPerBar * ticksPerBeat) + (rhythm.start * ticksPerBeat / 4);
    const duration = rhythm.duration * ticksPerBeat / 4;

    chord.forEach((note, idx) => {
      midiEvents.push({
        id: eventId++, type: 'noteOn', tick: tick, note: note,
        velocity: rhythm.velocity - (idx * 3), channel: 1,
        duration: duration
      });
    });
  });
}

midiEvents.sort((a, b) => a.tick - b.tick);

return {
  json: {
    instrument: 'chords',
    events: midiEvents,
    channel: 1
  }
};

// Combine all MIDI tracks into one multi-track MIDI file
const params = $('Validate Parameters').first().json;
const drums = $('Generate Drums').first().json;
const bass = $('Generate Bass').first().json;
const chords = $('Generate Chords').first().json;

const { bpm, bars, key, scale } = params;
const ticksPerBeat = 480;
const beatsPerBar = 4;

// Combine all events
const allEvents = [
  ...drums.events.map(e => ({ ...e, track: 0, trackName: 'Drums' })),
  ...bass.events.map(e => ({ ...e, track: 1, trackName: 'Bass' })),
  ...chords.events.map(e => ({ ...e, track: 2, trackName: 'Chords' }))
];

// Sort all events by tick
allEvents.sort((a, b) => a.tick - b.tick);

const midiData = {
  format: 1, // Multi-track format
  tracks: 3,
  ticksPerBeat: ticksPerBeat,
  bpm: bpm,
  key: key,
  scale: scale,
  tracksData: [
    {
      name: 'Drums',
      channel: 9,
      events: drums.events
    },
    {
      name: 'Bass',
      channel: 0,
      events: bass.events
    },
    {
      name: 'Chords',
      channel: 1,
      events: chords.events
    }
  ],
  allEvents: allEvents,
  totalTicks: bars * beatsPerBar * ticksPerBeat,
  durationSeconds: (bars * beatsPerBar * 60) / bpm
};

const filename = `house_music_${key}_${scale}_${bpm}bpm_${bars}bars.mid`;

return {
  json: {
    midiData: midiData,
    filename: filename,
    metadata: {
      generator: 'n8n House Music MIDI Generator',
      bpm: bpm,
      bars: bars,
      key: key,
      scale: scale,
      totalEvents: allEvents.length,
      durationSeconds: midiData.durationSeconds,
      timestamp: params.timestamp
    }
  }
};

// Output summary and MIDI data
const data = $input.first().json;
const { metadata, filename, midiData } = data;

console.log('=== House Music MIDI Generated ===' );
console.log(`File: ${filename}`);
console.log(`BPM: ${metadata.bpm}`);
console.log(`Key: ${metadata.key} ${metadata.scale}`);
console.log(`Bars: ${metadata.bars}`);
console.log(`Duration: ${metadata.durationSeconds.toFixed(2)}s`);
console.log(`Total MIDI Events: ${metadata.totalEvents}`);
console.log(`Tracks: Drums (${midiData.tracksData[0].events.length} events), Bass (${midiData.tracksData[1].events.length} events), Chords (${midiData.tracksData[2].events.length} events)`);

return {
  json: data
};
